import {test,expect,type Page} from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import {createServer,type ViteDevServer} from 'vite';
import {fileURLToPath} from 'node:url';
import {mkdir} from 'node:fs/promises';
test.describe.configure({mode:'serial'});let server:ViteDevServer,url:string;
const evidence=fileURLToPath(new URL('../evidence/',import.meta.url));
test.beforeAll(async()=>{server=await createServer({configFile:false,root:fileURLToPath(new URL('../fixtures/',import.meta.url)),esbuild:{jsx:'automatic'},server:{host:'127.0.0.1',port:0,fs:{allow:[fileURLToPath(new URL('../../../../',import.meta.url))]}},logLevel:'silent'});await server.listen();const address=server.httpServer!.address();if(!address||typeof address==='string')throw new Error();url=`http://127.0.0.1:${address.port}`;await mkdir(evidence,{recursive:true});});
test.afterAll(async()=>{await server?.close();});
async function ready(page:Page,query=''){await page.emulateMedia({reducedMotion:'reduce'});await page.setViewportSize({width:1120,height:850});await page.goto(url+query);await expect(page.getByRole('heading',{name:'Notes',exact:true})).toBeVisible();await expect(page.locator('.notes-workspace')).toHaveCSS('display','flex');await expect(page.locator('style[data-tiptap-style]')).toHaveCount(0);await page.evaluate(()=>document.fonts.ready);}
async function open(page:Page){await page.getByRole('button',{name:/Public field notes/}).click();await expect(page.getByRole('textbox',{name:'Note body',exact:true})).toBeVisible();}
for(const theme of ['dark','light'])test(`${theme} real rich editor, tasks and no implicit Save`,async({page})=>{await ready(page,`?theme=${theme}`);await open(page);await expect(page.getByRole('checkbox',{name:'Task: Review the public checklist'})).not.toBeChecked();await expect(page.locator('output')).toHaveText('No write observed.');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-notes-editor.png`,fullPage:true});await page.getByRole('checkbox',{name:'Task: Review the public checklist',exact:true}).check();await expect(page.locator('output')).toHaveText('Observed draft 1.');await expect(page.getByRole('button',{name:/Public field notes/})).toContainText('Draft differs');await page.getByRole('button',{name:'Save note',exact:true}).click();await expect(page.locator('output')).toHaveText('Observed save 2.');});
for(const theme of ['dark','light'])test(`${theme} empty library creates one recoverable draft`,async({page})=>{await ready(page,`?state=empty&theme=${theme}`);await expect(page.getByText('No notes yet. Create a note to begin.')).toBeVisible();await page.screenshot({path:`${evidence}/${theme}-notes-empty.png`,fullPage:true});await page.getByRole('button',{name:'New note',exact:true}).click();await expect(page.getByRole('textbox',{name:'Note title'})).toHaveValue('Untitled note');await expect(page.locator('output')).toHaveText('Observed draft 1.');});
test('slash menu keyboard creates actual task, Unicode and undo',async({page})=>{await ready(page,'?state=empty');await page.getByRole('button',{name:'New note',exact:true}).click();const body=page.getByRole('textbox',{name:'Note body',exact:true});await body.fill('/');await body.press('ArrowDown');await expect(page.getByRole('listbox',{name:'Insert block'}).getByRole('option',{name:'Heading 1',exact:true})).toHaveAttribute('aria-selected','true');await body.evaluate(element=>{element.dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true,data:''}));element.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',isComposing:true,bubbles:true,cancelable:true}));element.dispatchEvent(new CompositionEvent('compositionend',{bubbles:true,data:''}));});await expect(page.getByRole('listbox')).toBeVisible();await body.press('Escape');await expect(body).toHaveText('/');await body.fill('/task');await expect(page.getByRole('listbox',{name:'Insert block'})).toBeVisible();await page.screenshot({path:`${evidence}/dark-notes-slash.png`,fullPage:true});await body.press('Enter');await body.pressSequentially('Public task');await expect(page.getByRole('checkbox',{name:'Task: Public task'})).toBeVisible();await body.press('End');await body.pressSequentially(' 日本語 🪶');await expect(body).toContainText('日本語');await page.getByRole('button',{name:'Undo',exact:true}).click();await expect(body).not.toContainText('🪶');await page.getByRole('button',{name:'Redo',exact:true}).click();await expect(body).toContainText('🪶');});
test('plain paste never parses markup, external URLs or images',async({page})=>{await ready(page);await open(page);const requests:string[]=[];page.on('request',request=>{if(!request.url().startsWith(url))requests.push(request.url());});const body=page.getByRole('textbox',{name:'Note body',exact:true});await body.focus();await body.evaluate(element=>{const clipboardData=new DataTransfer();clipboardData.setData('text/plain','<script>public</script> https://example.org/image');clipboardData.setData('text/html','<img src="https://example.org/image">');element.dispatchEvent(new ClipboardEvent('paste',{clipboardData,bubbles:true,cancelable:true}));});await expect(body).toContainText('<script>public</script>');await expect(body.locator('a,img,script')).toHaveCount(0);expect(requests).toEqual([]);});
test('500ms title/body drafts and explicit CtrlS preserve Unicode',async({page})=>{await ready(page);await open(page);const title=page.getByRole('textbox',{name:'Note title'});await title.fill('Public 日本語');await expect(page.locator('output')).toHaveText('Observed draft 1.');await title.press('Control+s');await expect(page.locator('output')).toHaveText('Observed save 2.');await page.getByRole('searchbox',{name:'Search notes'}).fill('日本語');await expect(page.getByRole('button',{name:/Public 日本語/})).toBeVisible();});
test('pending Save held keys and composing input do not duplicate',async({page})=>{await ready(page,'?state=pending');await open(page);const title=page.getByRole('textbox',{name:'Note title'});await title.fill('Pending public note');await title.press('Control+s');await expect(page.locator('output')).toHaveText('Observed save 1.');await title.evaluate(element=>{element.dispatchEvent(new KeyboardEvent('keydown',{key:'s',ctrlKey:true,repeat:true,bubbles:true,cancelable:true}));element.dispatchEvent(new KeyboardEvent('keydown',{key:'s',ctrlKey:true,isComposing:true,bubbles:true,cancelable:true}));});await page.screenshot({path:`${evidence}/dark-notes-save-pending.png`,fullPage:true});await expect(page.locator('output')).toHaveText('Observed save 1.');await expect(page.getByRole('button',{name:'Save note',exact:true})).toHaveAttribute('aria-busy','true');});
for(const mode of ['conflict','unknown'])test(`${mode} retains local edits, confirmed Reload never replays`,async({page})=>{await ready(page,`?state=${mode}&theme=light`);await open(page);const title=page.getByRole('textbox',{name:'Note title'});await title.fill('Keep these local edits');await title.press('Control+s');await expect(page.getByRole('alert')).toContainText('uncertain');await expect(page.getByRole('button',{name:'Save note',exact:true})).toBeDisabled();await page.screenshot({path:`${evidence}/light-notes-${mode}.png`,fullPage:true});await page.getByRole('button',{name:'Reload stored note',exact:true}).click();await expect(page.getByRole('alertdialog')).toContainText('Your local edits stay here');await expect(page.getByRole('button',{name:'Keep editing',exact:true})).toBeFocused();await page.getByRole('button',{name:'Reload stored note now',exact:true}).click();await expect(title).toHaveValue('Keep these local edits');await expect(page.locator('output')).toHaveText('Observed save 1.');await expect(page.getByRole('button',{name:'Retry draft',exact:true})).toBeVisible();await page.screenshot({path:`${evidence}/light-notes-${mode}-reconciled.png`,fullPage:true});});
test('failed native close allows Keep editing or explicit loss choice',async({page})=>{await ready(page,'?state=unknown');await open(page);await page.getByRole('textbox',{name:'Note title'}).fill('Unsure close');await page.evaluate(async()=>{await (window as unknown as {requestNotesClose:()=>Promise<boolean>}).requestNotesClose();});await expect(page.getByRole('alertdialog')).toContainText('Latest changes');await page.screenshot({path:`${evidence}/dark-notes-close-recovery.png`,fullPage:true});await page.getByRole('button',{name:'Keep editing',exact:true}).click();await expect(page.getByRole('textbox',{name:'Note title'})).toHaveValue('Unsure close');await page.getByRole('button',{name:'Close Notes',exact:true}).click();await page.getByRole('button',{name:'Close without latest changes',exact:true}).click();await expect(page.locator('output')).toHaveText('Observed close request.');});
test('loading and unavailable search remain actionable',async({page})=>{await ready(page,'?state=loading');await expect(page.getByText('Loading notes…',{exact:true})).toBeVisible();await page.screenshot({path:`${evidence}/dark-notes-loading.png`,fullPage:true});await ready(page,'?state=list-error&theme=light');await expect(page.getByRole('button',{name:'Retry search'})).toBeVisible();await expect(page.getByText('No notes yet. Create a note to begin.')).toHaveCount(0);await page.screenshot({path:`${evidence}/light-notes-search-error.png`,fullPage:true});});
test('200% editing, slash Escape and bounded paste keep controls reachable',async({page})=>{await ready(page);await open(page);await page.evaluate(()=>{document.documentElement.style.fontSize='200%';});const body=page.getByRole('textbox',{name:'Note body',exact:true});await body.press('Control+End');await body.press('Enter');await body.pressSequentially('/heading');await expect(page.getByRole('listbox')).toBeVisible();await body.press('Escape');await expect(page.getByRole('listbox')).toHaveCount(0);await body.evaluate(element=>{const clipboardData=new DataTransfer();clipboardData.setData('text/plain','x'.repeat(65537));element.dispatchEvent(new ClipboardEvent('paste',{clipboardData,bubbles:true,cancelable:true}));});await expect(page.getByRole('alert')).toContainText('64 KiB');await page.getByRole('button',{name:'Save note',exact:true}).scrollIntoViewIfNeeded();expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);const save=page.getByRole('button',{name:'Save note',exact:true});const rect=await save.boundingBox();expect(rect!.y).toBeGreaterThanOrEqual(0);expect(rect!.y+rect!.height).toBeLessThanOrEqual(850);const pin=page.getByRole('button',{name:'Pin note',exact:true});await pin.scrollIntoViewIfNeeded();const pinRect=await pin.boundingBox();expect(pinRect!.y).toBeGreaterThanOrEqual(0);expect(pinRect!.y+pinRect!.height).toBeLessThanOrEqual(850);const archive=page.getByRole('button',{name:'Archive note',exact:true});await archive.scrollIntoViewIfNeeded();const archiveRect=await archive.boundingBox();expect(archiveRect!.y).toBeGreaterThanOrEqual(0);expect(archiveRect!.y+archiveRect!.height).toBeLessThanOrEqual(850);const trash=page.getByRole('button',{name:'Move to Trash',exact:true});await trash.scrollIntoViewIfNeeded();const trashRect=await trash.boundingBox();expect(trashRect!.y).toBeGreaterThanOrEqual(0);expect(trashRect!.y+trashRect!.height).toBeLessThanOrEqual(850);await body.scrollIntoViewIfNeeded();await page.screenshot({path:`${evidence}/dark-notes-200-percent.png`});});

test('mounting a recovered rich draft preserves its explanation without an implicit write',async({page})=>{await ready(page,'?state=recovered');await page.getByRole('button',{name:/Public recovered draft/}).click();const body=page.getByRole('textbox',{name:'Note body',exact:true});await expect(body).toBeVisible();await body.focus();await page.waitForTimeout(650);await expect(page.getByText('Recovered draft. Save explicitly to replace the last saved version.',{exact:true})).toBeVisible();await expect(page.locator('output')).toHaveText('No write observed.');await expect(body.locator(':scope > p')).toHaveCount(1);await expect(page.getByRole('textbox',{name:'Note title'})).toHaveValue('Public recovered draft');await body.press('Control+End');await body.press('Enter');await body.press('Enter');await body.pressSequentially('Public deliberate recovery edit');await expect(body.locator(':scope > p').last()).toHaveText('Public deliberate recovery edit');await expect(page.locator('output')).toHaveText('Observed draft 1.');});

for(const theme of ['dark','light'])test(`${theme} explicit Markdown export explains plaintext and preserves saved-state distinction`,async({page})=>{await ready(page,`?theme=${theme}`);await open(page);await expect(page.getByText('Export stores your latest draft',{exact:false})).toContainText('unencrypted Markdown');await page.getByRole('button',{name:'Export Markdown',exact:true}).click();await expect(page.locator('output')).toHaveText('Observed export 1.');await expect(page.getByRole('status').filter({hasText:'Markdown exported.'})).toContainText('Markdown exported. The file is unencrypted.');expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-notes-export.png`,fullPage:true});});
test('native chooser cancellation leaves the note editable without replay',async({page})=>{await ready(page,'?state=export-cancelled');await open(page);await page.getByRole('button',{name:'Export Markdown',exact:true}).click();await expect(page.getByRole('status').filter({hasText:'Export cancelled'})).toContainText('Export cancelled');await expect(page.getByRole('textbox',{name:'Note title'})).toBeEnabled();await expect(page.locator('output')).toHaveText('Observed export 1.');});
test('pending export freezes editing and native-close intent until the chooser settles',async({page})=>{await ready(page,'?state=export-pending');await open(page);await page.getByRole('button',{name:'Export Markdown',exact:true}).click();await expect(page.locator('output')).toHaveText('Observed export 1.');await expect(page.getByRole('textbox',{name:'Note title'})).toBeDisabled();await expect(page.getByRole('button',{name:'Save note',exact:true})).toBeDisabled();await expect(page.getByRole('textbox',{name:'Note body'})).toHaveAttribute('contenteditable','false');await page.getByRole('button',{name:'Close Notes',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Finish or cancel');await page.screenshot({path:`${evidence}/dark-notes-export-pending.png`,fullPage:true});await page.evaluate(()=>{(window as unknown as {resolveNoteExport:()=>void}).resolveNoteExport();});await expect(page.getByRole('textbox',{name:'Note title'})).toBeEnabled();await expect(page.locator('output')).toHaveText('Observed export 1.');});
test('unknown export says check the selected file and never automatically replays',async({page})=>{await ready(page,'?state=export-unknown&theme=light');await open(page);await page.getByRole('button',{name:'Export Markdown',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Check the selected file');await expect(page.locator('output')).toHaveText('Observed export 1.');await page.screenshot({path:`${evidence}/light-notes-export-unknown.png`,fullPage:true});});

for(const theme of ['dark','light'])test(`${theme} Pinned only is owner-filtered and Unpin retains the exact selected editor`,async({page})=>{await ready(page,`?state=pin-filter&theme=${theme}`);await open(page);const library=page.getByRole('list',{name:'Saved notes'}),filter=page.getByRole('checkbox',{name:'Pinned only',exact:true});await expect(library.getByRole('button')).toHaveCount(2);await filter.focus();await filter.press('Space');await expect(library.getByRole('button')).toHaveCount(1);await expect(library).toContainText('Pinned public reference');await expect(library).toContainText('Pinned');await expect(page.getByRole('textbox',{name:'Note title'})).toHaveValue('Public field notes');await expect(page.locator('output')).toHaveText('No write observed.');await expect(filter).toBeFocused();expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-notes-pinned-filter.png`,fullPage:true});const search=page.getByRole('searchbox',{name:'Search notes'});await search.fill('field');await expect(library.getByRole('button')).toHaveCount(0);await search.fill('');await expect(library.getByRole('button')).toHaveCount(1);await library.getByRole('button',{name:/Pinned public reference/}).click();await page.getByRole('button',{name:'Unpin note',exact:true}).click();await expect(library.getByRole('button')).toHaveCount(0);await expect(page.getByRole('textbox',{name:'Note title'})).toHaveValue('Pinned public reference');await expect(page.getByRole('button',{name:'Pin note',exact:true})).toBeEnabled();await expect(page.locator('output')).toHaveText('Observed pin 1: unpinned.');await expect(page.getByText('No pinned notes match this search.',{exact:false})).toBeVisible();await page.screenshot({path:`${evidence}/${theme}-notes-unpin-filter-empty.png`,fullPage:true});await filter.uncheck();await expect(library.getByRole('button')).toHaveCount(2);await expect(library.getByRole('button',{name:/Pinned public reference/})).toHaveAttribute('aria-current','true');});
test('pending Pin is not optimistic, ignores held keys and refuses editing/export/New/native close',async({page})=>{await ready(page,'?state=pin-pending');await open(page);await page.getByRole('textbox',{name:'Note title'}).fill('Public pending pin draft');const pin=page.getByRole('button',{name:'Pin note',exact:true});await pin.click();await expect(page.locator('output')).toHaveText('Observed pin 1: pinned.');await expect(pin).toHaveAttribute('aria-busy','true');await expect(page.getByRole('button',{name:'Unpin note',exact:true})).toHaveCount(0);await expect(page.getByRole('textbox',{name:'Note title'})).toBeDisabled();await expect(page.getByRole('textbox',{name:'Note body'})).toHaveAttribute('contenteditable','false');await expect(page.getByRole('searchbox',{name:'Search notes'})).toBeDisabled();await expect(page.getByRole('checkbox',{name:'Pinned only',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Save note',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Export Markdown',exact:true})).toBeDisabled();await pin.evaluate(element=>{element.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',isComposing:true,bubbles:true,cancelable:true}));});await pin.focus();await page.keyboard.down('Enter');await page.keyboard.down('Enter');await page.keyboard.up('Enter');await expect(page.getByRole('button',{name:'New note',exact:true})).toHaveAttribute('aria-disabled','true');await page.getByRole('button',{name:'New note',exact:true}).dispatchEvent('click');await page.getByRole('button',{name:'Close Notes',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Wait for the pin change');await expect(page.locator('output')).toHaveText('Observed pin 1: pinned.');await page.screenshot({path:`${evidence}/dark-notes-pin-pending.png`,fullPage:true});await page.evaluate(()=>{(window as unknown as {resolveNotePin:()=>void}).resolveNotePin();});await expect(page.getByRole('button',{name:'Unpin note',exact:true})).toBeVisible();await expect(page.getByRole('textbox',{name:'Note title'})).toHaveValue('Public pending pin draft');});
test('unknown Pin blocks mutation until confirmed Reload without replay or losing local edits',async({page})=>{await ready(page,'?state=pin-unknown&theme=light');await open(page);await page.getByRole('button',{name:'Pin note',exact:true}).click();await expect(page.getByRole('alert')).toContainText('pin change could not be confirmed');await expect(page.getByRole('button',{name:'Pin note',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Save note',exact:true})).toBeDisabled();await page.getByRole('textbox',{name:'Note title'}).fill('Public retained pin edit');await expect(page.locator('output')).toHaveText('Observed pin 1: pinned.');await page.screenshot({path:`${evidence}/light-notes-pin-unknown.png`,fullPage:true});await page.getByRole('button',{name:'Reload stored note',exact:true}).click();await expect(page.getByRole('button',{name:'Keep editing',exact:true})).toBeFocused();await page.getByRole('button',{name:'Reload stored note now',exact:true}).click();await expect(page.getByRole('textbox',{name:'Note title'})).toHaveValue('Public retained pin edit');await expect(page.getByRole('button',{name:'Pin note',exact:true})).toBeEnabled();await expect(page.locator('output')).toHaveText('Observed pin 1: pinned.');await page.screenshot({path:`${evidence}/light-notes-pin-reconciled.png`,fullPage:true});});
test('missing Pin capability remains visibly unavailable with no synthetic success',async({page})=>{await ready(page,'?state=pin-missing&theme=light');await open(page);await expect(page.getByRole('button',{name:'Pin note',exact:true})).toBeDisabled();await expect(page.getByText('Pinning is unavailable. Reopen Notes to reconnect.',{exact:true})).toBeVisible();await expect(page.locator('output')).toHaveText('No write observed.');await page.screenshot({path:`${evidence}/light-notes-pin-unavailable.png`,fullPage:true});});
test('known Pin refusal preserves the current state and permits deliberate retry only',async({page})=>{await ready(page,'?state=pin-denied');await open(page);await page.getByRole('button',{name:'Pin note',exact:true}).click();await expect(page.getByRole('alert')).toContainText('pin change was not accepted');await expect(page.getByRole('button',{name:'Pin note',exact:true})).toBeEnabled();await expect(page.getByRole('button',{name:'Unpin note',exact:true})).toHaveCount(0);await page.screenshot({path:`${evidence}/dark-notes-pin-denied.png`,fullPage:true});await page.getByRole('button',{name:'Pin note',exact:true}).click();await expect(page.getByRole('button',{name:'Unpin note',exact:true})).toBeVisible();await expect(page.locator('output')).toHaveText('Observed pin 2: pinned.');});

for(const theme of ['dark','light'])test(`${theme} Archive keeps a readonly editor and Restore uses the owner archive/pin filters`,async({page})=>{await ready(page,`?state=archive-library&theme=${theme}`);await open(page);const library=page.getByRole('list',{name:'Saved notes'}),title=page.getByRole('textbox',{name:'Note title'}),body=page.getByRole('textbox',{name:'Note body',exact:true}),archived=page.getByRole('checkbox',{name:'Show archived notes',exact:true});await expect(library.getByRole('button')).toHaveCount(1);await title.fill('Public archived draft');await page.getByRole('button',{name:'Archive note',exact:true}).click();await expect(page.locator('output')).toHaveText('Observed archive 1: archived.');await expect(library.getByRole('button')).toHaveCount(0);await expect(title).toHaveValue('Public archived draft');await expect(title).not.toBeEditable();await expect(body).toHaveAttribute('contenteditable','false');await expect(body).toHaveAttribute('aria-readonly','true');await expect(page.getByRole('checkbox',{name:'Task: Review the public checklist',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Save note',exact:true})).toBeDisabled();await title.press('Control+s');await expect(page.locator('output')).toHaveText('Observed archive 1: archived.');await expect(page.getByText('Archived note. Restore this note before editing.',{exact:true})).toBeVisible();expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);await page.screenshot({path:`${evidence}/${theme}-notes-archived-readonly.png`,fullPage:true});if(theme==='dark'){await page.evaluate(()=>{document.documentElement.style.fontSize='200%';});const restore=page.getByRole('button',{name:'Restore note',exact:true});await restore.scrollIntoViewIfNeeded();const rect=await restore.boundingBox();expect(rect!.y).toBeGreaterThanOrEqual(0);expect(rect!.y+rect!.height).toBeLessThanOrEqual(850);await page.screenshot({path:`${evidence}/dark-notes-archive-200-percent.png`});await page.evaluate(()=>{document.documentElement.style.fontSize='100%';});}await archived.focus();await archived.press('Space');await expect(library.getByRole('button')).toHaveCount(2);await page.getByRole('checkbox',{name:'Pinned only',exact:true}).check();await expect(library.getByRole('button')).toHaveCount(1);await library.getByRole('button',{name:/Archived public reference/}).click();await expect(title).not.toBeEditable();await expect(library).toContainText('Archived');await expect(library).toContainText('Pinned');await page.screenshot({path:`${evidence}/${theme}-notes-archive-filter.png`,fullPage:true});await page.getByRole('button',{name:'Restore note',exact:true}).click();await expect(page.locator('output')).toHaveText('Observed archive 2: restored.');await expect(library.getByRole('button')).toHaveCount(0);await expect(title).toHaveValue('Archived public reference');await expect(title).toBeEditable();await expect(body).toHaveAttribute('contenteditable','true');await expect(page.getByRole('checkbox',{name:'Task: Review the public checklist',exact:true})).toBeEnabled();await expect(page.getByRole('button',{name:'Unpin note',exact:true})).toBeVisible();await page.screenshot({path:`${evidence}/${theme}-notes-restored-editor.png`,fullPage:true});await archived.uncheck();await expect(library.getByRole('button')).toHaveCount(1);await expect(library.getByRole('button',{name:/Archived public reference/})).toHaveAttribute('aria-current','true');});
