test('Archive closes a live slash menu and readonly command paths leave the displayed document unchanged',async({page})=>{await ready(page);await open(page);const body=page.getByRole('textbox',{name:'Note body',exact:true});await body.press('Control+End');await body.press('Enter');await body.pressSequentially('/task');await expect(page.getByRole('listbox',{name:'Insert block'})).toBeVisible();const content=await body.innerHTML();await page.getByRole('button',{name:'Archive note',exact:true}).click();await expect(page.getByRole('button',{name:'Restore note',exact:true})).toBeVisible();await expect(page.getByRole('listbox',{name:'Insert block'})).toHaveCount(0);await expect(body).toHaveAttribute('contenteditable','false');await body.evaluate(element=>{element.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));const clipboardData=new DataTransfer();clipboardData.setData('text/plain','Not an archived edit');element.dispatchEvent(new ClipboardEvent('paste',{clipboardData,bubbles:true,cancelable:true}));});expect(await body.innerHTML()).toBe(content.replaceAll('type="checkbox"','type="checkbox" disabled=""'));await page.waitForTimeout(650);await expect(page.locator('output')).toHaveText('Observed archive 1: archived.');});

