// Slash menu reachability: the active option must lie inside every actual clipping ancestor and the viewport, and be hit-testable.
async function activeSlashOptionVisible(page:Page){return page.evaluate(()=>{const option=document.querySelector<HTMLElement>('[role="listbox"][aria-label="Insert block"] [role="option"][aria-selected="true"]');const popover=option?.closest<HTMLElement>('.notes-slash-popover');if(!option||!popover)return {ok:false,reason:'no active option'};
 // Visible region of an element: the viewport intersected with every scrolling/clipping ancestor's client box.
 const region=(from:HTMLElement|null)=>{let top=0,bottom=innerHeight,left=0,right=innerWidth;for(let node=from;node;node=node.parentElement){const style=getComputedStyle(node);if(/(auto|scroll|hidden|clip)/u.test(style.overflowY+style.overflowX)){const box=node.getBoundingClientRect();top=Math.max(top,box.top+node.clientTop);bottom=Math.min(bottom,box.top+node.clientTop+node.clientHeight);left=Math.max(left,box.left+node.clientLeft);right=Math.min(right,box.left+node.clientLeft+node.clientWidth);}}return {top,bottom,left,right};};
 const within=(rect:DOMRect,clip:{top:number;bottom:number;left:number;right:number})=>rect.top>=clip.top-0.5&&rect.bottom<=clip.bottom+0.5&&rect.left>=clip.left-0.5&&rect.right<=clip.right+0.5;
 const rect=option.getBoundingClientRect(),menu=popover.getBoundingClientRect(),optionClip=region(option.parentElement),menuClip=region(popover.parentElement);const hit=document.elementFromPoint(rect.left+rect.width/2,rect.top+rect.height/2);
 return {ok:within(rect,optionClip)&&within(menu,menuClip)&&!!hit&&option.contains(hit),reason:`option ${rect.top}..${rect.bottom} in ${optionClip.top}..${optionClip.bottom}; menu ${menu.top}..${menu.bottom} in ${menuClip.top}..${menuClip.bottom}`};});}
// ProseMirror adopts a keyboard-moved DOM selection on the asynchronous selectionchange event; let it settle before typing.
async function settle(page:Page){await page.evaluate(()=>new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve()))));}
async function openSlashAtEnd(page:Page){const body=page.getByRole('textbox',{name:'Note body',exact:true});await body.focus();await body.press('Control+End');await settle(page);await body.press('Enter');await body.press('/');await expect(page.getByRole('listbox',{name:'Insert block'})).toBeVisible();return body;}
async function caretInBody(page:Page){return page.evaluate(()=>{const selection=getSelection();const body=document.querySelector('[role="textbox"][aria-label="Note body"]');return !!selection?.anchorNode&&!!body?.contains(selection.anchorNode)&&document.activeElement===body;});}
for(const scale of ['100%','150%','200%'])test(`slash menu active option stays inside the actual clipping region at ${scale} text through Up/Down and filtering`,async({page})=>{await ready(page);await open(page);await page.evaluate(value=>{document.documentElement.style.fontSize=value;},scale);const body=await openSlashAtEnd(page);
 expect(await activeSlashOptionVisible(page)).toMatchObject({ok:true});
 for(const key of ['ArrowDown','ArrowDown','ArrowDown','ArrowDown','ArrowDown','ArrowDown','ArrowDown','ArrowDown','ArrowDown','ArrowUp','ArrowUp']){await body.press(key);expect(await activeSlashOptionVisible(page),key).toMatchObject({ok:true});expect(await caretInBody(page)).toBe(true);}
 const scroller=await page.locator('.notes-editor').evaluate(element=>element.scrollTop);await body.pressSequentially('li');await expect(page.getByRole('listbox',{name:'Insert block'}).getByRole('option')).toHaveCount(3);expect(await activeSlashOptionVisible(page)).toMatchObject({ok:true});expect(await page.locator('.notes-editor').evaluate(element=>element.scrollTop)).toBe(scroller);
 if(scale==='150%')await page.screenshot({path:`${instrument}/dark-slash-150-percent-bottom.png`});
 await body.press('Escape');await expect(page.getByRole('listbox')).toHaveCount(0);await expect(body).toHaveText(/\/li$/u);expect(await caretInBody(page)).toBe(true);});
test('slash menu stays reachable in a narrow window at the bottom of a long document and inserts the chosen block',async({page})=>{await ready(page,'?theme=light');await open(page);await page.setViewportSize({width:560,height:700});const body=page.getByRole('textbox',{name:'Note body',exact:true});await body.focus();await body.press('Control+End');await settle(page);for(let line=0;line<14;line+=1){await body.press('Enter');await body.pressSequentially(`Public line ${line}`);}
 await body.press('Enter');await body.press('/');await expect(page.getByRole('listbox',{name:'Insert block'})).toBeVisible();expect(await activeSlashOptionVisible(page)).toMatchObject({ok:true});for(let step=0;step<9;step+=1){await body.press('ArrowDown');expect(await activeSlashOptionVisible(page)).toMatchObject({ok:true});}
 await expect(page.getByRole('listbox',{name:'Insert block'}).getByRole('option',{name:'Divider',exact:true})).toHaveAttribute('aria-selected','true');await page.screenshot({path:`${instrument}/light-slash-narrow-bottom.png`});await body.press('Enter');await expect(page.getByRole('listbox')).toHaveCount(0);await expect(body.locator('hr')).toHaveCount(1);expect(await caretInBody(page)).toBe(true);});
